    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_vtop_ffi_fn_method_core_cached_timetable(
        it,
        
        FfiConverterString.lower(`flow`),_status)
}
    }
    )
    }
    

    
