                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_vtop_ffi_fn_free_httptransport(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_vtop_ffi_fn_clone_httptransport(handle, status)
        }
    }

    
    @Throws(TransportException::class)
    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
    override suspend fun `send`(`request`: HttpRequest) : HttpResponse {
        return uniffiRustCallAsync(
        callWithHandle { uniffiHandle ->
            UniffiLib.uniffi_vtop_ffi_fn_method_httptransport_send(
                uniffiHandle,
                
        FfiConverterTypeHttpRequest.lower(`request`),
            )
        },
        { future, callback, continuation -> UniffiLib.ffi_vtop_ffi_rust_future_poll_rust_buffer(future, callback, continuation) },
        { future, continuation -> UniffiLib.ffi_vtop_ffi_rust_future_complete_rust_buffer(future, continuation) },
        { future -> UniffiLib.ffi_vtop_ffi_rust_future_free_rust_buffer(future) },
        // lift function
        { FfiConverterTypeHttpResponse.lift(it) },
        // Error FFI converter
        TransportException.ErrorHandler,
    )
    }

    

    


    
    
    /**
     * @suppress
     */
    companion object
    
}



// Put the implementation in an object so we don't pollute the top-level namespace
internal object uniffiCallbackInterfaceHttpTransport {
    internal object `send`: UniffiCallbackInterfaceHttpTransportMethod0 {
        override fun callback(`uniffiHandle`: Long,`request`: RustBuffer.ByValue,`uniffiFutureCallback`: UniffiForeignFutureCompleteRustBuffer,`uniffiCallbackData`: Long,`uniffiOutDroppedCallback`: UniffiForeignFutureDroppedCallbackStruct,) {
            val uniffiObj = FfiConverterTypeHttpTransport.handleMap.get(uniffiHandle)
            val makeCall = suspend { ->
                uniffiObj.`send`(
                    FfiConverterTypeHttpRequest.lift(`request`),
                )
            }
            val uniffiHandleSuccess = { returnValue: HttpResponse ->
                val uniffiResult = UniffiForeignFutureResultRustBuffer.UniffiByValue(
                    FfiConverterTypeHttpResponse.lower(returnValue),
                    UniffiRustCallStatus.ByValue()
                )
                uniffiResult.write()
                uniffiFutureCallback.callback(uniffiCallbackData, uniffiResult)
            }
            val uniffiHandleError = { callStatus: UniffiRustCallStatus.ByValue ->
                uniffiFutureCallback.callback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer.UniffiByValue(
                        RustBuffer.ByValue(),
                        callStatus,
                    ),
                )
            }
            uniffiTraitInterfaceCallAsyncWithError(
                makeCall,
                uniffiHandleSuccess,
                uniffiHandleError,
                { e: TransportException -> FfiConverterTypeTransportError.lower(e) },
                uniffiOutDroppedCallback
            )
        }
    }

    internal object uniffiFree: UniffiCallbackInterfaceFree {
        override fun callback(handle: Long) {
            FfiConverterTypeHttpTransport.handleMap.remove(handle)
        }
    }

    internal object uniffiClone: UniffiCallbackInterfaceClone {
        override fun callback(handle: Long): Long {
            return FfiConverterTypeHttpTransport.handleMap.clone(handle)
        }
    }

    internal var vtable = UniffiVTableCallbackInterfaceHttpTransport.UniffiByValue(
        uniffiFree,
        uniffiClone,
        `send`,
    )

    // Registers the foreign callback with the Rust side.
    // This method is generated for each callback interface.
    internal fun register(lib: UniffiLib) {
        lib.uniffi_vtop_ffi_fn_init_callback_vtable_httptransport(vtable)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeHttpTransport: FfiConverter<HttpTransport, Long> {
    internal val handleMap = UniffiHandleMap<HttpTransport>()

    override fun lower(value: HttpTransport): Long {
        if (value is HttpTransportImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): HttpTransport {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return HttpTransportImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): HttpTransport {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: HttpTransport) = 8UL

    override fun write(value: HttpTransport, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


