/**
 * @suppress
 */
public object FfiConverterTypeSharedCookies: FfiConverter<SharedCookies, Long> {
    internal val handleMap = UniffiHandleMap<SharedCookies>()

    override fun lower(value: SharedCookies): Long {
        if (value is SharedCookiesImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): SharedCookies {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return SharedCookiesImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): SharedCookies {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: SharedCookies) = 8UL

    override fun write(value: SharedCookies, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



