     * 0 without credits.
     */
    var `semesterGpa`: kotlin.Double
    , 
    var `credits`: kotlin.Double
    , 
    /**
     * The CGPA typed in, when it reads as 0–10.
     */
    var `current`: kotlin.Double?
    , 
    /**
     * The CGPA after the semester; none without a current one.
     */
    var `projected`: kotlin.Double?
    , 
    /**
     * `projected - current`.
     */
    var `delta`: kotlin.Double
    , 
    /**
     * The target given, else the next quarter point above the current CGPA
     * (9 without one).
     */
    var `target`: kotlin.Double
    , 
    /**
     * The semester GPA the target needs; none without a current CGPA or
     * credits.
     */
    var `needed`: kotlin.Double?
    , 
    var `outlook`: TargetOutlook?
    , 
    /**
     * The letter nearest the semester GPA (for its colour).
     */
    var `letter`: kotlin.String
    
){
    

    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeGpaPlan: FfiConverterRustBuffer<GpaPlan> {
    override fun read(buf: ByteBuffer): GpaPlan {
        return GpaPlan(
            FfiConverterDouble.read(buf),
            FfiConverterDouble.read(buf),
            FfiConverterOptionalDouble.read(buf),
            FfiConverterOptionalDouble.read(buf),
            FfiConverterDouble.read(buf),
            FfiConverterDouble.read(buf),
            FfiConverterOptionalDouble.read(buf),
            FfiConverterOptionalTypeTargetOutlook.read(buf),
            FfiConverterString.read(buf),
        )
    }

    override fun allocationSize(value: GpaPlan) = (
            FfiConverterDouble.allocationSize(value.`semesterGpa`) +
            FfiConverterDouble.allocationSize(value.`credits`) +
            FfiConverterOptionalDouble.allocationSize(value.`current`) +
            FfiConverterOptionalDouble.allocationSize(value.`projected`) +
            FfiConverterDouble.allocationSize(value.`delta`) +
            FfiConverterDouble.allocationSize(value.`target`) +
            FfiConverterOptionalDouble.allocationSize(value.`needed`) +
            FfiConverterOptionalTypeTargetOutlook.allocationSize(value.`outlook`) +
            FfiConverterString.allocationSize(value.`letter`)
    )

    override fun write(value: GpaPlan, buf: ByteBuffer) {
            FfiConverterDouble.write(value.`semesterGpa`, buf)
            FfiConverterDouble.write(value.`credits`, buf)
            FfiConverterOptionalDouble.write(value.`current`, buf)
            FfiConverterOptionalDouble.write(value.`projected`, buf)
            FfiConverterDouble.write(value.`delta`, buf)
            FfiConverterDouble.write(value.`target`, buf)
            FfiConverterOptionalDouble.write(value.`needed`, buf)
            FfiConverterOptionalTypeTargetOutlook.write(value.`outlook`, buf)
            FfiConverterString.write(value.`letter`, buf)
    }
}



