/**
 * One hop, headers final: the transport adds no cookies and follows no redirects. No
 * `Debug`: headers carry cookies, the body a password or OTP.
 */
data class HttpRequest (
    var `method`: kotlin.String
    , 
    var `url`: kotlin.String
    , 
    var `headers`: List<Header>
    , 
    var `body`: kotlin.ByteArray
    , 
    /**
     * The whole hop, body included.
     */
    var `timeoutMs`: kotlin.UInt
    , 
    var `connectTimeoutMs`: kotlin.UInt
    , 
    /**
     * A download: write the body to this file (created or truncated) and answer with
     * [`HttpResponse::saved_size`] and no body.
     */
    var `downloadTo`: kotlin.String?
    
){
    

    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeHttpRequest: FfiConverterRustBuffer<HttpRequest> {
    override fun read(buf: ByteBuffer): HttpRequest {
        return HttpRequest(
            FfiConverterString.read(buf),
            FfiConverterString.read(buf),
            FfiConverterSequenceTypeHeader.read(buf),
            FfiConverterByteArray.read(buf),
            FfiConverterUInt.read(buf),
            FfiConverterUInt.read(buf),
            FfiConverterOptionalString.read(buf),
        )
    }

    override fun allocationSize(value: HttpRequest) = (
            FfiConverterString.allocationSize(value.`method`) +
            FfiConverterString.allocationSize(value.`url`) +
            FfiConverterSequenceTypeHeader.allocationSize(value.`headers`) +
            FfiConverterByteArray.allocationSize(value.`body`) +
            FfiConverterUInt.allocationSize(value.`timeoutMs`) +
            FfiConverterUInt.allocationSize(value.`connectTimeoutMs`) +
            FfiConverterOptionalString.allocationSize(value.`downloadTo`)
    )

    override fun write(value: HttpRequest, buf: ByteBuffer) {
            FfiConverterString.write(value.`method`, buf)
            FfiConverterString.write(value.`url`, buf)
            FfiConverterSequenceTypeHeader.write(value.`headers`, buf)
            FfiConverterByteArray.write(value.`body`, buf)
            FfiConverterUInt.write(value.`timeoutMs`, buf)
            FfiConverterUInt.write(value.`connectTimeoutMs`, buf)
            FfiConverterOptionalString.write(value.`downloadTo`, buf)
    }
}



/**
 * The answer as it came (a 3xx too), every header kept, the body decompressed. `url` is
 * the request's.
 */
data class HttpResponse (
    var `status`: kotlin.UShort
    , 
    var `headers`: List<Header>
    , 
    var `url`: kotlin.String
    , 
    var `body`: kotlin.ByteArray
    , 
    /**
     * The body's size when it went to [`HttpRequest::download_to`].
     */
    var `savedSize`: kotlin.ULong?
    
){
    

    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeHttpResponse: FfiConverterRustBuffer<HttpResponse> {
    override fun read(buf: ByteBuffer): HttpResponse {
        return HttpResponse(
            FfiConverterUShort.read(buf),
            FfiConverterSequenceTypeHeader.read(buf),
            FfiConverterString.read(buf),
            FfiConverterByteArray.read(buf),
            FfiConverterOptionalULong.read(buf),
        )
    }

    override fun allocationSize(value: HttpResponse) = (
            FfiConverterUShort.allocationSize(value.`status`) +
            FfiConverterSequenceTypeHeader.allocationSize(value.`headers`) +
            FfiConverterString.allocationSize(value.`url`) +
            FfiConverterByteArray.allocationSize(value.`body`) +
            FfiConverterOptionalULong.allocationSize(value.`savedSize`)
    )

    override fun write(value: HttpResponse, buf: ByteBuffer) {
            FfiConverterUShort.write(value.`status`, buf)
            FfiConverterSequenceTypeHeader.write(value.`headers`, buf)
            FfiConverterString.write(value.`url`, buf)
            FfiConverterByteArray.write(value.`body`, buf)
            FfiConverterOptionalULong.write(value.`savedSize`, buf)
    }
}



