        when(value) {
            is CalendarKind.Instructional -> {
                buf.putInt(1)
                Unit
            }
            is CalendarKind.WorkingDay -> {
                buf.putInt(2)
                FfiConverterOptionalInt.write(value.`follows`, buf)
                Unit
            }
            is CalendarKind.LabFat -> {
                buf.putInt(3)
