/**
 * Why a call failed. The text field is `reason`, not `message`: Kotlin
 * exceptions already have a `message` and UniFFI would declare it twice.
 */
sealed class CoreException: kotlin.Exception() {
    
    class Offline(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    class VtopUnavailable(
        
        val `reason`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class InvalidCredentials(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * A re-login during a fetch wants the emailed OTP.
     */
    class OtpRequired(
        
        val `reason`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * `submit_otp` got a wrong or expired code; VTOP's text.
     */
    class OtpRejected(
        
        val `reason`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class NotSignedIn(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * No semester picked yet (or VTOP no longer lists the pick): the
     * student picks one from [`Core::fetch_semesters`] first.
     */
    class SemesterNeeded(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    class Other(
        
        val `reason`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): CoreException = FfiConverterTypeCoreError.lift(error_buf)
    }

    
}

